from pathlib import Pathimport jsonHISTORY_ROOT = (    Path("AI-Archive")    / "integrity"    / "history")def load_history(model: str):    """    Load all integrity history records for a model.    Returns:        list[dict]    """    model_dir = HISTORY_ROOT / model    if not model_dir.exists():        return []    history = []    for file in sorted(        model_dir.glob("*.json")    ):        with open(            file,            "r",            encoding="utf-8",        ) as f:            history.append(                json.load(f)            )    return history